(3859516, 546659, 80795, '<td valign="top">What a beautiful picture of a mountain and the whale and the mountains.  Love it!</td>', 'What a beautiful picture of a mountain and the whale and the mountains.  Love it!', '2007-07-02 18:14:46.000000', NULL, 1),
(3859518, 546812, 9906, '<td valign="top">The shallow crop top to bottom makes this feel a little tight.  Nice idea for a shot though.  Would have been cool if all the flip flops matched up with the nail polish.<br/>TC</td>', 'The shallow crop top to bottom makes this feel a little tight.  Nice idea for a shot though.  Would have been cool if all the flip flops matched up with the nail polish.TC', '2007-07-02 18:15:37.000000', NULL, 1),
