(3859905, 545033, 23458, '<td valign="top">Good catch here - the lighting is a bit harsh and the composition a little out of wack, but not a bad effort. Certainly meets the challenge nicely.</td>', 'Good catch here - the lighting is a bit harsh and the composition a little out of wack, but not a bad effort. Certainly meets the challenge nicely.', '2007-07-02 19:37:39.000000', NULL, 1),
(3859909, 546776, 23458, '<td valign="top">Nice and crisp. Well composed. 7.</td>', 'Nice and crisp. Well composed. 7.', '2007-07-02 19:38:20.000000', NULL, 1),
(3859911, 546695, 51386, '<td valign="top">What a cool idea. Maybe a wiii bit over exposed, but i love the concept! 6</td>', 'What a cool idea. Maybe a wiii bit over exposed, but i love the concept! 6', '2007-07-02 19:38:35.000000', NULL, 1),
(3859921, 546864, 23458, '<td valign="top">A bit too grainy, and the focus is not quite right, but the idea and composition are spot on.</td>', 'A bit too grainy, and the focus is not quite right, but the idea and composition are spot on.', '2007-07-02 19:41:16.000000', NULL, 1),
(3859926, 546296, 23458, '<td valign="top">I''m not sure that the vingette is helping you here - if anything it detracts from the subject. Still, I love the look of concentration on his face.</td>', 'I''m not sure that the vingette is helping you here - if anything it detracts from the subject. Still, I love the look of concentration on his face.', '2007-07-02 19:42:10.000000', NULL, 1),
(3859936, 546747, 23458, '<td valign="top">Beautiful animal - good stop motion here. I think this would have been improved somewhat if you''d got down a little lower and given the front hoof some context/grounding. You could also probably crop a centimetre or two from the top without losing anything.</td>', 'Beautiful animal - good stop motion here. I think this would have been improved somewhat if you''d got down a little lower and given the front hoof some context/grounding. You could also probably crop a centimetre or two from the top without losing anything.', '2007-07-02 19:44:19.000000', NULL, 1),
(3859941, 546860, 23458, '<td valign="top">Hehehe - well caught. Made me cringe and smile at the same time. The animal is beautiful and the dog''s expression priceless.</td>', 'Hehehe - well caught. Made me cringe and smile at the same time. The animal is beautiful and the dog''s expression priceless.', '2007-07-02 19:45:13.000000', NULL, 1),
