(3885211, 546901, 40797, '<td valign="top">Amazing! Congratulatioins on your ribbon!!</td>', 'Amazing! Congratulatioins on your ribbon!!', '2007-07-09 10:46:24.000000', NULL, 0),
(3885227, 545459, 29269, '<td valign="top">One of my favorites for the challenge. Technically, really sub-standard for DPC. However, the challenge theme is met 100%. This is a posterchild image for how an excellent shot of a shoehorned subject (I go to mountains on my weekends, I look at bugs for my weekend, I enjoy dogs/cats/mice/snakes/gerbils on the weekend) can surpass otherwise perfectly fitting but poorly executed shot.<br/> <br/>Best of luck to the little fellow!</td>', 'One of my favorites for the challenge. Technically, really sub-standard for DPC. However, the challenge theme is met 100%. This is a posterchild image for how an excellent shot of a shoehorned subject (I go to mountains on my weekends, I look at bugs for my weekend, I enjoy dogs/cats/mice/snakes/gerbils on the weekend) can surpass otherwise perfectly fitting but poorly executed shot. Best of luck to the little fellow!', '2007-07-09 10:53:10.000000', NULL, 0),
(3885238, 546352, 61651, '<td valign="top">And a very nice deck it is too - I like the celebratory champagne!  I like the composition, especially that chunky swath of sky.</td>', 'And a very nice deck it is too - I like the celebratory champagne!  I like the composition, especially that chunky swath of sky.', '2007-07-09 10:57:09.000000', NULL, 0),
