(3885609, 546374, 70888, '<td valign="top">wow,im desperately trying to get these kind of results(been offered shooting bands at my local concert hall)awesome shot thanx for the inspiration</td>', 'wow,im desperately trying to get these kind of results(been offered shooting bands at my local concert hall)awesome shot thanx for the inspiration', '2007-07-09 12:31:18.000000', NULL, 0),
(3885624, 546901, 66384, '<td valign="top">That''s some beautiful processing you did, to bring out those rich colors and the lovely DOF. The rule of thirds served you well too. Congratulations on your ribbon and your beautiful photo of a beautiful scene.</td>', 'That''s some beautiful processing you did, to bring out those rich colors and the lovely DOF. The rule of thirds served you well too. Congratulations on your ribbon and your beautiful photo of a beautiful scene.', '2007-07-09 12:33:39.000000', NULL, 0),
